import{_ as e,o,c as r,a2 as t}from"./chunks/framework.D8Tso2Ul.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Build & Serve","text":"Manual de Uso Oficial","tagline":"Plataforma de gestión de Seguridad y Salud en el Trabajo (SST) para obras de construcción · CCHC Chile","image":{"src":"/logo-bs.svg","alt":"Build & Serve"},"actions":[{"theme":"brand","text":"Guía de Inicio →","link":"/guia-inicio/"},{"theme":"alt","text":"Ver módulos","link":"/modulos/"},{"theme":"alt","text":"Cumplimiento DS 44","link":"/ds44/"}]},"features":[{"icon":"🚀","title":"Guía de Inicio","details":"Instalación, configuración y onboarding de un nuevo tenant en la plataforma.","link":"/guia-inicio/"},{"icon":"📋","title":"DS44 & Normativa","details":"Cumplimiento del Supremo Decreto 44. Documentos obligatorios, fases de obra y firmas.","link":"/ds44/"},{"icon":"🧩","title":"Módulos","details":"Documentación completa de los 11 módulos de la plataforma.","link":"/modulos/"},{"icon":"👥","title":"Roles de Usuario","details":"Qué puede hacer cada rol. Tabla comparativa de permisos por módulo.","link":"/roles/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(l,a,s,d,c,u){return o(),r("div",null,[...a[0]||(a[0]=[t('<h2 id="¿que-es-build-serve" tabindex="-1">¿Qué es Build &amp; Serve? <a class="header-anchor" href="#¿que-es-build-serve" aria-label="Permalink to &quot;¿Qué es Build &amp; Serve?&quot;">​</a></h2><p><strong>Build &amp; Serve</strong> es una plataforma SaaS multi-tenant que digitaliza la gestión de Seguridad y Salud en el Trabajo (SST) en obras de construcción chilenas. Reemplaza los procesos basados en papel por un sistema único que centraliza documentos, firmas, incidentes, capacitaciones y reportería, con cumplimiento integrado del <strong>Supremo Decreto 44</strong>.</p><p>Desarrollada por <strong>The Code Cookers</strong> durante el Hackathon CChC 2025 — <em>Seguridad sin Papeleo</em>, en colaboración con la Cámara Chilena de la Construcción (CCHC).</p><h2 id="novedades-—-supremo-decreto-44" tabindex="-1">Novedades — Supremo Decreto 44 <a class="header-anchor" href="#novedades-—-supremo-decreto-44" aria-label="Permalink to &quot;Novedades — Supremo Decreto 44&quot;">​</a></h2><p>El <strong>DS 44</strong> actualizó el marco de gestión preventiva de riesgos laborales en Chile. Build &amp; Serve incorpora su cumplimiento de forma nativa:</p><ul><li><strong>Documentos obligatorios por fase de obra</strong> precreados automáticamente.</li><li><strong>Matrices de riesgo (MIPER / MIPPER)</strong> generadas con asistencia de IA.</li><li><strong>Entrega de EPP</strong> con firma de trabajador y supervisor.</li><li><strong>Capacitaciones Art. 16</strong> con registro de asistencia y firma del relator.</li><li><strong>Trazabilidad inmutable</strong> de cada firma con PIN, IP y timestamp.</li></ul><p>➡️ Revisa la sección <a href="/manual/ds44/">DS44 &amp; Normativa</a> para el detalle completo.</p><div class="warning custom-block"><p class="custom-block-title">Consulta legal pendiente</p><p>La validez jurídica del PIN como firma electrónica ante un fiscalizador del DS 44 está siendo evaluada con la Dirección del Trabajo (acuerdo reunión CCHC 2026-06-10). La funcionalidad opera con normalidad, pero <strong>no debe usarse como única prueba legal</strong> hasta obtener respuesta oficial. Más detalles en <a href="/manual/ds44/firmas-digitales.html">Firmas digitales y DS44</a>.</p></div><h2 id="mapa-rapido" tabindex="-1">Mapa rápido <a class="header-anchor" href="#mapa-rapido" aria-label="Permalink to &quot;Mapa rápido&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quiero…</th><th>Ir a</th></tr></thead><tbody><tr><td>Ingresar a la plataforma por primera vez</td><td><a href="/manual/guia-inicio/instalacion.html">Cómo ingresar</a></td></tr><tr><td>Poner una obra en marcha paso a paso</td><td><a href="/manual/guia-inicio/primeros-pasos.html">Primeros pasos</a></td></tr><tr><td>Entender qué exige el DS 44</td><td><a href="/manual/ds44/">¿Qué es el DS 44?</a></td></tr><tr><td>Aprender a usar cada parte de la plataforma</td><td><a href="/manual/modulos/">Módulos</a></td></tr><tr><td>Saber qué puede hacer mi rol</td><td><a href="/manual/roles/">Roles de Usuario</a></td></tr></tbody></table>',10)])])}const g=e(i,[["render",n]]);export{p as __pageData,g as default};
